// Deye-Konfiguration - PRO KUNDE ANPASSEN (VoltPilot-Service, nicht der Kunde).
// communication: 'solarman_v5' (EMPFOHLEN, robust, Modbus in Solarman-V5 ueber TCP 8899)
//              | 'at_cli' (AT-CLI ueber UDP 48899 - veraltet, oft flaky hinter NAT).
// Fuer solarman_v5 ist die DATALOGGER-Seriennummer (serial) PFLICHT - das ist NICHT
// die Wechselrichter-Seriennummer! Sie steht z. B. im AP-SSID "AP_<serial>", auf dem
// Logger-Label oder auf der Status-Seite des Loggers.
// family: 'string' | 'hybrid_1p' | 'hybrid_3p' | 'micro'.
// hybrid_3p deckt die 3-phasigen Hybride ab: SG04LP3 (LV, 2 MPPT) UND
// SG01HP3 (HV, SUN-29.9..50K-SG01HP3-EU-BM3/BM4, 3-4 MPPT) - gleiche high-map.
// Vorzeichen (Netz/Batterie) ERST AM GERAET kalibrieren - siehe DEYE.md.
flow.set('deye_wechselrichter', [
  {
    id: 'wr1',
    ip: '192.168.1.50',          // IP des Deye-WiFi-Loggers (Bestaetigtes Captain-Geraet: 192.168.0.28)
    communication: 'solarman_v5', // 'solarman_v5' (empfohlen) | 'at_cli'
    port: 8899,                   // solarman_v5: 8899 | at_cli: 48899
    serial: 0,                    // solarman_v5 PFLICHT: Datalogger-Seriennummer (Zahl!) - NICHT die WR-Seriennummer (Captain-Logger: 2985159064)
    mb_slave_id: 1,               // Modbus-Unit-ID (Standard 1)
    family: 'hybrid_3p',          // Captain-Geraet: SUN-*-SG01HP3-EU (3-phasig HV Hybrid)
    invert_grid_sign: false,
    invert_batt_sign: false,
    // Nur hybrid_3p HV bei Bedarf 10 (Dezawatt-Firmware) - siehe DEYE.md Abschnitt 2
    power_scale: 1,
    // Nur string/micro: erlaubte Stufen der Wirkleistungsbegrenzung in %
    // (leer = 1-%-Schritte), z. B. [0, 25, 50, 75, 100].
    limit_stages: []
  }
]);
node.status({ fill: 'grey', shape: 'dot', text: 'Konfiguration geladen' });
return null;

// Baut den Leseplan (Modbus-Bloecke) fuer den konfigurierten Wechselrichter und
// waehlt die Kommunikationsmethode:
//   communication: 'solarman_v5' (empfohlen, TCP 8899) -> Ausgang 2 (Solarman-V5 lesen)
//   communication: 'at_cli'      (AT-CLI, UDP 48899)   -> Ausgang 1 (deye -xmb)
// Registerkarten/Skalierung: edge-app/nodered/deye/deye-decode.js (getestet).
const READS = {
  string:    [{ start: 0x0050, count: 0x0002 }],
  hybrid_1p: [{ start: 0x00a9, count: 0x0016 }],
  hybrid_3p: [{ start: 0x024c, count: 0x0058 }],
  micro:     [{ start: 0x0056, count: 0x0002 }]
};
const list = flow.get('deye_wechselrichter') || [];
