if (f.load) { const w = fieldValue(f.load); if (w !== undefined) reading.load_kw = toKw(w); }
if (f.grid) { let w = fieldValue(f.grid);   if (w !== undefined) { if (cfg.invert_grid_sign) w = -w; reading.power_kw = toKw(w); } }
