  d.low = soc; d.step = 1;
  msg.payload = ['-t', d.target, '-xmb', '024C0001'].join(' '); // high-map SoC
  node.status({ fill: 'blue', shape: 'dot', text: 'sondiere high map (0x024C)...' });
  return [msg, null];
}
