if (lowOk && !highOk) family = 'hybrid_1p';
else if (highOk && !lowOk) family = 'hybrid_3p';
const txt = family
  ? ('Familie erkannt: ' + family + ' (low=' + d.low + ', high=' + d.high + ')')
  : ('unklar - low=' + d.low + ', high=' + d.high + ' (string/micro manuell)');
node.status({ fill: family ? 'green' : 'yellow', shape: family ? 'dot' : 'ring', text: txt });
msg.payload = { family, low_soc: d.low, high_soc: d.high };
return [null, msg];

// Wirkleistungsbegrenzung fuer string/micro -> Register 0x0028 (0..100 %).
// Eingang: msg.payload = gewuenschte Begrenzung in Prozent.
// DIES ist die klar benannte Steuerstelle: hier bildet VoltPilot seine
// Kurve / §14a-Vorgabe auf die vom Geraet akzeptierten Stufen ab
// (cfg.limit_stages). Batteriesteuerung fuer Hybride ist BEWUSST NICHT hier -
// siehe den Abschnitt "Ausgeklammert" in DEYE.md.
const list = flow.get('deye_wechselrichter') || [];
const cfg = list[0];
if (!cfg) { node.status({ fill: 'red', shape: 'ring', text: 'keine Konfiguration' }); return null; }
if (!(cfg.family === 'string' || cfg.family === 'micro')) {
  node.status({ fill: 'yellow', shape: 'ring', text: cfg.family + ': kein 0x0028-Schreibpfad' });
  return null;
}
